package crm

import (
	"context"
	"fmt"
	"time"

	"github.com/domainry-evals/m1-crm/generated/capabilities"
	"github.com/domainry-evals/m1-crm/generated/data"
	"github.com/domainry-evals/m1-crm/generated/schema"
)

const staleReminderBatchSize = 200

// DispatchStaleReminders implements the project-owned lead.dispatch_stale_reminders Handler.
func DispatchStaleReminders(ctx context.Context, caps capabilities.DispatchStaleRemindersCapabilities, input capabilities.DispatchStaleRemindersInput) (capabilities.DispatchStaleRemindersOutput, error) {
	if input.ScheduledAt.IsZero() {
		return capabilities.DispatchStaleRemindersOutput{}, dispatchStaleRemindersError("invalid_input", "scheduled_at is required")
	}
	if input.ScheduledAt.Weekday() == time.Saturday || input.ScheduledAt.Weekday() == time.Sunday {
		return capabilities.DispatchStaleRemindersOutput{}, dispatchStaleRemindersError("invalid_schedule", "stale reminders run only on weekdays")
	}
	if caps.Execution == nil || caps.Lead == nil || caps.LeadReminderReceipt == nil || caps.Notifications == nil {
		return capabilities.DispatchStaleRemindersOutput{}, dispatchStaleRemindersError("capability_unavailable", "required Action capability is unavailable")
	}
	principal := caps.Execution.Principal()
	if !principal.Known || principal.RoleKey != "crm_scheduler" {
		return capabilities.DispatchStaleRemindersOutput{}, dispatchStaleRemindersError("principal_invalid", "a known CRM scheduler principal is required")
	}

	cutoff := input.ScheduledAt.Add(-7 * 24 * time.Hour)
	leads, err := caps.Lead.List(ctx, data.NewLeadQuery().
		WhereStatusEqual(schema.LeadStatusContacted).
		WhereStatusChangedAtLessThan(cutoff).
		OrderByIDAscending().
		Page(1, staleReminderBatchSize))
	if err != nil {
		return capabilities.DispatchStaleRemindersOutput{}, err
	}
	if len(leads) > staleReminderBatchSize {
		return capabilities.DispatchStaleRemindersOutput{}, dispatchStaleRemindersError("unbounded_result", "lead query exceeded the authorized batch size")
	}

	location := input.ScheduledAt.Location()
	businessDate := time.Date(input.ScheduledAt.Year(), input.ScheduledAt.Month(), input.ScheduledAt.Day(), 0, 0, 0, 0, location)
	output := capabilities.DispatchStaleRemindersOutput{EligibleCount: int64(len(leads))}
	for _, lead := range leads {
		if lead.ID == "" || lead.UpdatedAt == "" || lead.OwnerID == "" || lead.CompanyName == "" || lead.Status != schema.LeadStatusContacted || lead.StatusChangedAt == nil || !lead.StatusChangedAt.Before(cutoff) {
			return capabilities.DispatchStaleRemindersOutput{}, dispatchStaleRemindersError("candidate_invalid", "lead query returned an ineligible or incomplete candidate")
		}

		dedupeKey := fmt.Sprintf("lead:%s:stale-contact:%s", lead.ID, businessDate.Format("2006-01-02"))
		exists, err := caps.LeadReminderReceipt.Exists(ctx, data.NewLeadReminderReceiptQuery().WhereDedupeKeyEqual(dedupeKey))
		if err != nil {
			return capabilities.DispatchStaleRemindersOutput{}, err
		}
		if exists {
			continue
		}

		receipt, err := caps.LeadReminderReceipt.Create(ctx, schema.CreateLeadReminderReceipt{
			BusinessDate: businessDate,
			DedupeKey:    dedupeKey,
			LeadID:       schema.NewLeadReminderReceiptLeadIDReference(lead.ID),
			RecipientID:  lead.OwnerID,
			Status:       schema.LeadReminderReceiptStatusDispatched,
		})
		if err != nil {
			return capabilities.DispatchStaleRemindersOutput{}, err
		}
		if receipt.ID == "" {
			return capabilities.DispatchStaleRemindersOutput{}, dispatchStaleRemindersError("mutation_invalid", "reminder receipt creation returned no identity")
		}

		companyName := lead.CompanyName
		sourceEventID := principal.RequestID
		if sourceEventID == "" {
			sourceEventID = dedupeKey
		}
		_, err = caps.Notifications.Dispatch(ctx, capabilities.DispatchStaleRemindersNotificationIntent{
			EventType:        "crm.stale_contact_reminder",
			SourceEventID:    sourceEventID,
			RecipientUserIDs: []string{lead.OwnerID},
			Surface:          approveConversionSurface,
			SubjectObjectKey: "lead",
			SubjectRecordID:  string(lead.ID),
			SubjectVersion:   lead.UpdatedAt,
			DedupeKey:        dedupeKey,
			GroupKey:         "lead:" + string(lead.ID),
			Alert:            true,
			OccurredAt:       input.ScheduledAt,
			Variables: []capabilities.DispatchStaleRemindersNotificationVariable{
				{Key: "company_name", StringValue: &companyName},
			},
		})
		if err != nil {
			return capabilities.DispatchStaleRemindersOutput{}, err
		}
		output.DispatchedCount++
	}

	return output, nil
}

func dispatchStaleRemindersError(suffix, message string) error {
	return &capabilities.BusinessError{Code: capabilities.DispatchStaleRemindersActionKey + "." + suffix, Message: message}
}
