func TestDispatchStaleRemindersCreatesOncePerLeadAndBusinessDate(t *testing.T) {
	scheduledAt := time.Date(2026, 8, 19, 9, 0, 0, 0, time.FixedZone("CST", 8*60*60))
	staleAt := scheduledAt.Add(-8 * 24 * time.Hour)
	leads := &dispatchStaleRemindersLeadStub{records: []schema.Lead{
		{ID: "lead-1", UpdatedAt: "rev-1", CompanyName: "Acme", OwnerID: "rep-1", Status: schema.LeadStatusContacted, StatusChangedAt: &staleAt},
		{ID: "lead-2", UpdatedAt: "rev-2", CompanyName: "Beta", OwnerID: "rep-2", Status: schema.LeadStatusContacted, StatusChangedAt: &staleAt},
	}}
	receipts := &dispatchStaleRemindersReceiptStub{existsResults: []bool{false, true}}
	notifications := &dispatchStaleRemindersNotificationStub{}

	output, err := DispatchStaleReminders(t.Context(), capabilities.DispatchStaleRemindersCapabilities{
		Execution:           dispatchStaleRemindersExecutionStub{principal: capabilities.Principal{Known: true, RoleKey: "crm_scheduler", RequestID: "schedule-run-1"}},
		Lead:                leads,
		LeadReminderReceipt: receipts,
		Notifications:       notifications,
	}, capabilities.DispatchStaleRemindersInput{ScheduledAt: scheduledAt})
	if err != nil {
		t.Fatalf("DispatchStaleReminders returned error: %v", err)
	}
	if output.EligibleCount != 2 || output.DispatchedCount != 1 {
		t.Fatalf("unexpected output: %+v", output)
	}
	if leads.listCalls != 1 || receipts.existsCalls != 2 || len(receipts.created) != 1 || len(notifications.intents) != 1 {
		t.Fatalf("unexpected effects: lists=%d exists=%d creates=%d notifications=%d", leads.listCalls, receipts.existsCalls, len(receipts.created), len(notifications.intents))
	}
	created := receipts.created[0]
	if created.LeadID.ID() != "lead-1" || created.RecipientID != "rep-1" || created.BusinessDate.Format("2006-01-02") != "2026-08-19" || created.Status != schema.LeadReminderReceiptStatusDispatched {
		t.Fatalf("unexpected receipt: %+v", created)
	}
	intent := notifications.intents[0]
	if intent.EventType != "crm.stale_contact_reminder" || intent.SourceEventID != "schedule-run-1" || intent.SubjectRecordID != "lead-1" || intent.SubjectVersion != "rev-1" || !intent.Alert {
		t.Fatalf("unexpected notification: %+v", intent)
	}
}

func TestDispatchStaleRemindersRejectsWeekendBeforeQuery(t *testing.T) {
	leads := &dispatchStaleRemindersLeadStub{}
	_, err := DispatchStaleReminders(t.Context(), capabilities.DispatchStaleRemindersCapabilities{}, capabilities.DispatchStaleRemindersInput{ScheduledAt: time.Date(2026, 8, 22, 9, 0, 0, 0, time.UTC)})
	assertDispatchStaleRemindersErrorCode(t, err, "lead.dispatch_stale_reminders.invalid_schedule")
	if leads.listCalls != 0 {
		t.Fatal("weekend schedule queried leads")
	}
}

func TestDispatchStaleRemindersRejectsMalformedCandidateWithoutEffects(t *testing.T) {
	scheduledAt := time.Date(2026, 8, 19, 9, 0, 0, 0, time.UTC)
	staleAt := scheduledAt.Add(-8 * 24 * time.Hour)
	receipts := &dispatchStaleRemindersReceiptStub{}
	notifications := &dispatchStaleRemindersNotificationStub{}
	_, err := DispatchStaleReminders(t.Context(), capabilities.DispatchStaleRemindersCapabilities{
		Execution:           dispatchStaleRemindersExecutionStub{principal: capabilities.Principal{Known: true, RoleKey: "crm_scheduler"}},
		Lead:                &dispatchStaleRemindersLeadStub{records: []schema.Lead{{ID: "lead-1", UpdatedAt: "rev-1", CompanyName: "Acme", OwnerID: "rep-1", Status: schema.LeadStatusQualified, StatusChangedAt: &staleAt}}},
		LeadReminderReceipt: receipts,
		Notifications:       notifications,
	}, capabilities.DispatchStaleRemindersInput{ScheduledAt: scheduledAt})
	assertDispatchStaleRemindersErrorCode(t, err, "lead.dispatch_stale_reminders.candidate_invalid")
	if len(receipts.created) != 0 || len(notifications.intents) != 0 {
		t.Fatal("invalid candidate produced effects")
	}
}

func assertDispatchStaleRemindersErrorCode(t *testing.T, err error, expected string) {
	t.Helper()
	var businessError *capabilities.BusinessError
	if !errors.As(err, &businessError) || businessError.Code != expected {
		t.Fatalf("expected %s, got %T %v", expected, err, err)
	}
}
