// UpdateOwnedDetails implements the project-owned lead.update_owned_details Handler.
func UpdateOwnedDetails(ctx context.Context, caps capabilities.UpdateOwnedDetailsCapabilities, input capabilities.UpdateOwnedDetailsInput) (capabilities.UpdateOwnedDetailsOutput, error) {
	if strings.TrimSpace(input.RequestID) == "" {
		return capabilities.UpdateOwnedDetailsOutput{}, updateOwnedDetailsError("invalid_input", "request_id is required")
	}
	if input.ContactName == nil && input.ContactPhone == nil && input.ExpectedAmount == nil && input.Source == nil {
		return capabilities.UpdateOwnedDetailsOutput{}, updateOwnedDetailsError("empty_patch", "at least one editable field is required")
	}
	if caps.Execution == nil || caps.Lead == nil {
		return capabilities.UpdateOwnedDetailsOutput{}, updateOwnedDetailsError("capability_unavailable", "required Action capability is unavailable")
	}

	principal := caps.Execution.Principal()
	leadID := caps.Execution.TargetID()
	if leadID == "" {
		return capabilities.UpdateOwnedDetailsOutput{}, updateOwnedDetailsError("invalid_target", "lead target is required")
	}
	lead, err := caps.Lead.GetForUpdate(ctx, leadID)
	if err != nil {
		return capabilities.UpdateOwnedDetailsOutput{}, err
	}
	if err := validateOwnedLead(capabilities.UpdateOwnedDetailsActionKey, principal, leadID, lead); err != nil {
		return capabilities.UpdateOwnedDetailsOutput{}, err
	}
	if lead.Status == schema.LeadStatusConverted || lead.Status == schema.LeadStatusLost {
		return capabilities.UpdateOwnedDetailsOutput{}, updateOwnedDetailsError("invalid_state", "terminal leads cannot be edited")
	}

	mutation := data.NewLeadUpdate(leadID).
		RequireStatusEqual(lead.Status, capabilities.UpdateOwnedDetailsActionKey+".stale_revision").
		WithExpectedUpdatedAt(lead.UpdatedAt)
	if input.ContactName != nil {
		value := strings.TrimSpace(*input.ContactName)
		if value == "" {
			mutation = mutation.ClearContactName()
		} else {
			mutation = mutation.SetContactName(value)
		}
	}
	if input.ContactPhone != nil {
		value := strings.TrimSpace(*input.ContactPhone)
		if value == "" {
			mutation = mutation.ClearContactPhone()
		} else {
			mutation = mutation.SetContactPhone(value)
		}
	}
	if input.ExpectedAmount != nil {
		if _, ok := parseCRMAmountCents(string(*input.ExpectedAmount)); !ok {
			return capabilities.UpdateOwnedDetailsOutput{}, updateOwnedDetailsError("amount_invalid", "expected amount must be a non-negative exact two-decimal value")
		}
		mutation = mutation.SetExpectedAmount(*input.ExpectedAmount)
	}
	if input.Source != nil {
		if input.Source.I18nKey() == "" {
			return capabilities.UpdateOwnedDetailsOutput{}, updateOwnedDetailsError("source_invalid", "source must be a declared value")
		}
		mutation = mutation.SetSource(schema.LeadSource(*input.Source))
	}

	updated, err := caps.Lead.ConditionalUpdate(ctx, mutation)
	if err != nil {
		return capabilities.UpdateOwnedDetailsOutput{}, err
	}
	if updated.ID != leadID || updated.UpdatedAt == "" || updated.Status.I18nKey() == "" {
		return capabilities.UpdateOwnedDetailsOutput{}, updateOwnedDetailsError("mutation_invalid", "lead mutation returned an incomplete result")
	}
	return capabilities.UpdateOwnedDetailsOutput{LeadID: leadID, Status: schema.LeadUpdateOwnedDetailsStatus(updated.Status)}, nil
}

func updateOwnedDetailsError(suffix, message string) error {
	return &capabilities.BusinessError{Code: capabilities.UpdateOwnedDetailsActionKey + "." + suffix, Message: message}
}
