func TestUpdateOwnedDetailsAppliesTypedPatchToOwnedLead(t *testing.T) {
	department := "dept-east"
	contact := " Ada "
	phone := " +86 123456 "
	amount := schema.LeadExpectedAmount("12345.67")
	source := schema.LeadUpdateOwnedDetailsSourceReferral
	leads := &transitionLeadStub{
		record:       schema.Lead{ID: "lead-1", UpdatedAt: "rev-1", OwnerID: "rep-1", OwnerDepartmentID: &department, Status: schema.LeadStatusContacted},
		updateResult: schema.Lead{ID: "lead-1", UpdatedAt: "rev-2", OwnerID: "rep-1", OwnerDepartmentID: &department, Status: schema.LeadStatusContacted},
	}
	output, err := UpdateOwnedDetails(t.Context(), capabilities.UpdateOwnedDetailsCapabilities{
		Execution: updateOwnedDetailsExecutionStub{principal: capabilities.Principal{Known: true, UserID: "rep-1", RoleKey: "sales_rep", DepartmentID: department}, targetID: "lead-1"},
		Lead:      leads,
	}, capabilities.UpdateOwnedDetailsInput{RequestID: "request-1", ContactName: &contact, ContactPhone: &phone, ExpectedAmount: &amount, Source: &source})
	if err != nil {
		t.Fatalf("UpdateOwnedDetails returned error: %v", err)
	}
	if output.LeadID != "lead-1" || output.Status != schema.LeadUpdateOwnedDetailsStatusContacted || leads.updateCalls != 1 {
		t.Fatalf("unexpected result: output=%+v updates=%d", output, leads.updateCalls)
	}
}

func TestUpdateOwnedDetailsRejectsEmptyPatchBeforeRead(t *testing.T) {
	_, err := UpdateOwnedDetails(t.Context(), capabilities.UpdateOwnedDetailsCapabilities{}, capabilities.UpdateOwnedDetailsInput{RequestID: "request-1"})
	assertUpdateOwnedDetailsErrorCode(t, err, "lead.update_owned_details.empty_patch")
}

func TestUpdateOwnedDetailsRejectsTerminalLeadWithoutMutation(t *testing.T) {
	department := "dept-east"
	contact := "Ada"
	leads := &transitionLeadStub{record: schema.Lead{ID: "lead-1", UpdatedAt: "rev-1", OwnerID: "rep-1", OwnerDepartmentID: &department, Status: schema.LeadStatusConverted}}
	_, err := UpdateOwnedDetails(t.Context(), capabilities.UpdateOwnedDetailsCapabilities{
