	}
}

func TestUpdateOwnedDetailsPropagatesStaleRevision(t *testing.T) {
	department := "dept-east"
	contact := "Ada"
	stale := errors.New("stale revision")
	leads := &transitionLeadStub{record: schema.Lead{ID: "lead-1", UpdatedAt: "rev-1", OwnerID: "rep-1", OwnerDepartmentID: &department, Status: schema.LeadStatusNew}, updateError: stale}
	_, err := UpdateOwnedDetails(t.Context(), capabilities.UpdateOwnedDetailsCapabilities{
		Execution: updateOwnedDetailsExecutionStub{principal: capabilities.Principal{Known: true, UserID: "rep-1", RoleKey: "sales_rep", DepartmentID: department}, targetID: "lead-1"},
		Lead:      leads,
	}, capabilities.UpdateOwnedDetailsInput{RequestID: "request-1", ContactName: &contact})
	if !errors.Is(err, stale) {
		t.Fatalf("expected stale revision, got %v", err)
	}
}

func assertUpdateOwnedDetailsErrorCode(t *testing.T, err error, expected string) {
	t.Helper()
	var businessError *capabilities.BusinessError
	if !errors.As(err, &businessError) || businessError.Code != expected {
		t.Fatalf("expected %s, got %T %v", expected, err, err)
	}
}

